import scopeJson from './scope.json';

/**
 * Which iPhone model/storage variants are priced by the evidence-calibrated model. Browser-safe on purpose: it imports only
 * the small scope.json (never the engine or the calibration), so the quote form can ask "is this device in scope?" without
 * the pricing logic reaching the browser bundle. scope.json is generated by
 * scripts/pricing-evidence/validate-evidence-engine.ts from the held-out validation.
 */
/** What to do with a quote whose group combination (or any parameter) was not validated for the model:
 *  price   quote it anyway (the model's held-out accuracy on such quotes met the thresholds)
 *  inspect manual inspection: no instant price (the existing pattern for unvalidated conditions)
 *  legacy  leave it to the existing engine, unchanged */
export type InferredPolicy = 'price' | 'inspect' | 'legacy';
export interface ScopeEntry {
  enabled: boolean; inferredPolicy: InferredPolicy; reason: string; storagesGb: number[];
  /** A model with no quotes of its own is priced with this sibling's calibration, every value labelled inferred (iPhone 12 Mini <- iPhone 12). */
  fallbackFrom?: string;
}
export const SCOPE = scopeJson as unknown as { version: string; models: Record<string, ScopeEntry> };

/** 'Apple iPhone 15 Pro Max' -> 'iPhone 15 Pro Max' */
export const evidenceModelKey = (model: string): string => String(model ?? '').trim().replace(/^apple\s+/i, '').replace(/\s+/g, ' ');

/** Capacity in GB from any catalog spelling: '256GB', '128 GB', '6 GB/128 GB', '12 GB/2 TB', '1TB'. */
export function storageGbOf(storage: string | undefined | null): number | null {
  const m = String(storage ?? '').match(/(\d+)\s*(GB|TB)\s*$/i);
  return m ? Number(m[1]) * (m[2].toUpperCase() === 'TB' ? 1024 : 1) : null;
}

/** True when this exact model/variant is priced by the evidence-calibrated model. Without a storage: any variant of the model. */
export function isAppleEvidenceModel(model: string, storage?: string | null): boolean {
  const entry = SCOPE.models[evidenceModelKey(model)];
  if (!entry?.enabled) return false;
  if (storage === undefined) return true;
  // any capacity of an enabled model: storagesGb lists where quotes were collected, not where the rules apply (they are relative to each variant's reference)
  return storageGbOf(storage) != null;
}
